import { resolve } from "node:path";
import { readFileSync } from "node:fs";
import { analysisJobSchema } from "../../lib/analysis-jobs";
import { completedJob } from "./analysis-job";
/** Generated by the synthetic backend workflow; no real photograph or inference. */
export function automaticWorkflowJob() {
  const fixture = JSON.parse(
    readFileSync(
      resolve(process.cwd(), "test/fixtures/automatic-targeting.json"),
      "utf8",
    ),
  );
  const job = analysisJobSchema.parse(fixture.job);
  job.status = "completed";
  job.connectorValidation ??= {
    references: [],
    evaluations: [],
    gates: job.automaticTargeting!.map((r) => ({
      objectId: r.objectId,
      status: "blocked",
      evaluationId: null,
      reason: "Independent connector validation is missing.",
    })),
  };
  job.result = completedJob({
    image: job.image,
    objects: [],
    provenance: {
      mode: "combined",
      reasoningModel: "synthetic",
      segmentationModel: "synthetic",
    },
  }).result;
  return job;
}
